function resolveFolder({path, rules}) {
  let best = null;
  let bestLen = -1;
  for (let i = 0; i < rules.length; i++) {
    const segs = rules[i][0];
    if (segs.length > path.length) continue;
    let match = true;
    for (let j = 0; j < segs.length; j++) {
      if (segs[j] !== path[j]) { match = false; break; }
    }
    if (match && segs.length >= bestLen) {
      bestLen = segs.length;
      best = rules[i][1];
    }
  }
  return bestLen === -1 ? null : best;
}

