function billable({sessions, pauses, free}) {
  const validSessions = (sessions || []).filter(([a, b]) => b > a);
  const validPauses = (pauses || []).filter(([a, b]) => b > a);
  let total = 0;
  for (const [s, e] of validSessions) {
    const covered = [];
    for (const [pa, pb] of validPauses) {
      const lo = Math.max(s, pa);
      const hi = Math.min(e, pb);
      if (hi > lo) covered.push([lo, hi]);
    }
    covered.sort((x, y) => x[0] - y[0]);
    let paused = 0;
    let curStart = null;
    let curEnd = null;
    for (const [lo, hi] of covered) {
      if (curStart === null) {
        curStart = lo;
        curEnd = hi;
      } else if (lo <= curEnd) {
        if (hi > curEnd) curEnd = hi;
      } else {
        paused += curEnd - curStart;
        curStart = lo;
        curEnd = hi;
      }
    }
    if (curStart !== null) paused += curEnd - curStart;
    const billableMinutes = Math.max(0, (e - s) - paused - (free || 0));
    total += billableMinutes;
  }
  return total;
}

