    for (const [c, d] of ps) {
      const lo = Math.max(a, c);
      const hi = Math.min(b, d);
      if (hi > lo) covered.push([lo, hi]);
    }
    covered.sort((x, y) => x[0] - y[0]);
    let paused = 0;
    let curStart = null;
    let curEnd = null;
    for (const [lo, hi] of covered) {
      if (curStart === null) {
        curStart = lo;
        curEnd = hi;
      } else if (lo <= curEnd) {
        if (hi > curEnd) curEnd = hi;
      } else {
        paused += curEnd - curStart;
        curStart = lo;
        curEnd = hi;
      }
    }
    if (curStart !== null) paused += curEnd - curStart;
    const billableMinutes = Math.max(0, (b - a) - paused - free);
    total += billableMinutes;
  }
  return total;
}

function billable({sessions, pauses, free}) {
  const ps = (pauses || []).filter(([a, b]) => b > a);
  let total = 0;
  for (const [a, b] of (sessions || [])) {
    if (b <= a) continue;
    const covered = [];
    for (const [c, d] of ps) {
      const lo = Math.max(a, c);
      const hi = Math.min(b, d);
      if (hi > lo) covered.push([lo, hi]);
    }
    covered.sort((x, y) => x[0] - y[0]);
    let paused = 0;
    let curStart = null;
    let curEnd = null;
    for (const [lo, hi] of covered) {
      if (curStart === null) {
        curStart = lo;
        curEnd = hi;
      } else if (lo <= curEnd) {
        if (hi > curEnd) curEnd = hi;
      } else {
        paused += curEnd - curStart;
        curStart = lo;
        curEnd = hi;
      }
    }
    if (curStart !== null) paused += curEnd - curStart;
    const billableMinutes = Math.max(0, (b - a) - paused - free);
    total += billableMinutes;
  }
  return total;
}
